package glitch

import data.glitch_lib

# Critical weak algorithms - exact matches only, no substrings
weak_algorithms := {"DES", "3DES", "RC2", "RC4", "MD2", "MD4", "MD5", "SHA0", "SHA1", "SHA_1", "DSA"}

# Weak hash patterns for function arguments (must be complete argument match)
weak_hash_args := {"sha1", "md5", "sha_1"}

# Weak modes - must be at word boundaries or specific contexts
weak_modes := {"ECB"}

# Disabled encryption values
disabled_encryption := {"none", "disabled", "no", "false", "off"}

# Core crypto attribute names - must match these exactly (case insensitive via regex)
core_crypto_attrs := {
    "algorithm", "encryption_algorithm", "hash_algorithm", 
    "digest", "signature_algorithm", "signing_algorithm",
    "block_cipher_mode", "mode_of_operation", "cipher",
    "protocol", "ssl_protocol", "tls_version", "ssl_version",
    "minimum_protocol_version", "cipher_suite", "cipher_suites",
    "ciphers", "kex_algorithms", "mac_algorithms"
}

# Storage/encryption enablement attributes
enablement_attrs := {
    "encryption", "storage_encrypted", "encryption_at_rest",
    "snapshot_encryption", "ebs_encrypted", "volume_encryption",
    "encryption_in_transit", "tls_enforced", "require_secure_transport"
}

# All crypto-related attributes combined
all_crypto_attrs := {k | k := core_crypto_attrs[_]} | {k | k := enablement_attrs[_]}

# Check if value is exact weak algorithm match
is_weak_algorithm(value) {
    value.ir_type == "String"
    alg := weak_algorithms[_]
    lower(value.value) == lower(alg)
}

is_weak_algorithm(value) {
    value.ir_type == "String"
    alg := weak_algorithms[_]
    regex.match(sprintf("^.*/%s$", [alg]), value.value)
}

is_weak_algorithm(value) {
    value.ir_type == "String"
    alg := weak_algorithms[_]
    regex.match(sprintf("^%s/.*$", [alg]), value.value)
}

is_weak_algorithm(value) {
    value.ir_type == "String"
    alg := weak_algorithms[_]
    regex.match(sprintf(".*_%s_.*", [alg]), value.value)
}

# Check for weak mode in cipher context (ECB)
is_weak_mode(value) {
    value.ir_type == "String"
    mode := weak_modes[_]
    val_lower := lower(value.value)
    # ECB must appear as word or in cipher context
    regex.match(sprintf(".*\\b%s\\b.*", [mode]), val_lower)
}

# Check for disabled encryption
is_disabled_encryption(value) {
    value.ir_type == "String"
    val_lower := lower(value.value)
    val_lower == disabled_encryption[_]
}

is_disabled_encryption(value) {
    value.ir_type == "Boolean"
    value.value == false
}

# Check attribute name matches crypto pattern
is_crypto_attribute(name) {
    attr := all_crypto_attrs[_]
    regex.match(sprintf("(?i)^%s$", [attr]), name)
}

is_crypto_attribute(name) {
    regex.match("(?i)^(sse_|kms_|ssl_|tls_|cipher_|hash_|sign_|encrypt_).*", name)
}

is_crypto_attribute(name) {
    regex.match("(?i).*_algorithm$", name)
}

is_crypto_attribute(name) {
    regex.match("(?i).*_spec(ification)?$", name)
}

is_crypto_attribute(name) {
    regex.match("(?i).*_policy$", name)
}

# Extract concrete value from nested IR structures
concrete_value(node) = val {
    node.ir_type == "String"
    val := node
} else = val {
    node.ir_type == "Boolean"
    val := node
} else = val {
    walk(node, [_, child])
    child.ir_type == "String"
    val := child
} else = val {
    walk(node, [_, child])
    child.ir_type == "Boolean"
    val := child
}

# Check FunctionCall for weak crypto arguments
check_function_call(node) {
    node.ir_type == "FunctionCall"
    regex.match("(?i)(hash|digest|encrypt|cipher|hmac)", node.name)
    arg := node.args[_]
    arg.ir_type == "String"
    lower(arg.value) == weak_hash_args[_]
}

# === DETECTION RULES ===

# Rule 1: Weak algorithm in crypto attribute
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    walk(parent, [_, node])

    node.ir_type == "Attribute"
    attr := node

    is_crypto_attribute(attr.name)

    val := concrete_value(attr.value)
    is_weak_algorithm(val)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of a broken or risky cryptographic algorithm - Avoid using weak, deprecated, or broken cryptographic algorithms. (CWE-327)"
    }
}

# Rule 2: Weak mode in crypto attribute
Glitch_Analysis[result] {
